let elem=document.getelemementById("profile_inner_id");const height=elem.clientHeight,width=elem.clientWidth;elem.addEventListener("mousemove",handleMove);function handleMove(e){const t=e.layerX,n=e.layerY,s=20*((t-width/2)/width),o=-20*((n-height/2)/height),i="perspective(500px) scale(1.1) rotateX("+o+"deg) rotateY("+s+"deg)";elem.style.transform=i}elem.addEventListener("mouseout",function(){elem.style.transform="perspective(500px) scale(1) rotateX(0) rotateY(0)"}),elem.addEventListener("mousedown",function(){elem.style.transform="perspective(500px) scale(0.9) rotateX(0) rotateY(0)"}),elem.addEventListener("mouseup",function(){elem.style.transform="perspective(500px) scale(1.1) rotateX(0) rotateY(0)"})